svg.metadata:
# On-prem LLM serving — Open-WebUI frontend over a vLLM GPU cluster. # Users reach a WAF-protected Open-WebUI chat frontend; the UI calls an # OpenAI-compatible inference router, which load-balances across GPU hosts # running vLLM. Model weights are pulled from an on-prem model store over NFS. # GPU hosts use the dedicated `gpu` glyph; the edge WAF uses the `waf` glyph. # The replica fan-outs are written as list endpoints (see connections: below). diagram: title: On-prem LLM — vLLM + Open-WebUI direction: down owner: ml-platform environment: on-prem
nodes: - id: users label: Users type: user - id: waf label: WAF type: waf ip: 10.30.0.10 # the chat frontend and its database are containers ON one docker host — # drawn INSIDE it, which is what "runs on" actually means - id: apphost label: app-host-01 type: metal # physical docker host — double border ip: 10.30.10.5 os: linux nodes: - id: webui label: Open-WebUI type: container # dockerized chat frontend — dotted border ip: 10.30.10.11 os: linux - id: pg label: webui-db type: container icon: db # containerized Postgres (chat history) ip: 10.30.10.21 os: linux - id: router label: Inference Router type: lb # OpenAI-compatible gateway, fans out to vLLM replicas ip: 10.30.20.9 os: linux - id: vllm1 label: vllm-01 type: gpu # GPU inference host — dedicated gpu glyph ip: 10.30.20.11 os: linux model: llama-3.1-70b tags: [a100] - id: vllm2 label: vllm-02 type: gpu ip: 10.30.20.12 os: linux model: llama-3.1-70b tags: [a100] - id: models label: Model Store type: storage # NFS export holding model weights ip: 10.30.20.30
groups: - id: edge label: Edge class: zone cidr: 10.30.0.0/24 nodes: [waf] - id: app label: App tier class: subnet cidr: 10.30.10.0/24 nodes: [apphost] # the containers come along inside it - id: gpu label: GPU cluster class: trust cidr: 10.30.20.0/24 nodes: [router, vllm1, vllm2, models]
connections: # edge labels follow "<proto>/<port> <context>" - {from: users, to: waf, label: "tcp/443 https", protocol: tcp, port: 443} - {from: waf, to: webui, label: "tcp/8080 http", protocol: tcp, port: 8080} - {from: webui, to: pg, label: "tcp/5432 postgres", protocol: tcp, port: 5432} - {from: webui, to: router, label: "tcp/8000 openai-api", protocol: tcp, port: 8000} # either end may be a LIST, which fans out into one connection per pair — # each inherits the label, protocol and port, and stays a separate edge, a # separate firewall rule, and separately marked when comparing - {from: router, to: [vllm1, vllm2], label: "tcp/8000 vllm", protocol: tcp, port: 8000} - {from: [vllm1, vllm2], to: models, label: "tcp/2049 nfs", protocol: tcp, port: 2049}
views: - {id: edge, title: "vLLM — edge path", focus: waf, depth: 1} - {id: inference, title: "vLLM — inference path", focus: router, depth: 2} - {id: gpu, title: "vLLM — gpu cluster", focus: gpu, depth: 1}
